package co.com.empresa.domain.type;import co.com.empresa.commons.exception.DomainException;import co.com.empresa.domain.constants.DomainErrors;import org.jeasy.random.EasyRandom;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class TypeTest {    private EasyRandom easyRandom;    @BeforeEach    void setUp() {        easyRandom = new EasyRandom();    }    @Test    @DisplayName("Should validate successfully when all required fields are present")    void validate_Success() {        Type type = easyRandom.nextObject(Type.class);        type.setTypeCategoryId(1L);        type.setName("Valid Name");        type.setCode("VALID_CODE");        assertDoesNotThrow(type::validate);    }    @Test    @DisplayName("Should throw exception when typeCategoryId is null")    void validate_NullCategoryId_ThrowsException() {        Type type = easyRandom.nextObject(Type.class);        type.setTypeCategoryId(null);        DomainException exception = assertThrows(DomainException.class, type::validate);        assertEquals(DomainErrors.ERROR_TYPE_CATEGORY_ID_EMPTY, exception.getMessage());    }    @Test    @DisplayName("Should throw exception when name is blank")    void validate_BlankName_ThrowsException() {        Type type = easyRandom.nextObject(Type.class);        type.setName(" ");        DomainException exception = assertThrows(DomainException.class, type::validate);        assertEquals(DomainErrors.ERROR_TYPE_NAME_EMPTY, exception.getMessage());    }    @Test    @DisplayName("Should throw exception when code is null")    void validate_NullCode_ThrowsException() {        Type type = easyRandom.nextObject(Type.class);        type.setCode(null);        DomainException exception = assertThrows(DomainException.class, type::validate);        assertEquals(DomainErrors.ERROR_TYPE_CODE_EMPTY, exception.getMessage());    }}